#include "tensorrt_backend.hpp"
#include "postprocess.hpp"
#include <opencv2/imgcodecs.hpp>
#include <opencv2/imgproc.hpp>
#include <chrono>
#include <deque>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <numeric>
struct Pending{size_t slot;std::chrono::steady_clock::time_point submitted;};
int main(int argc,char**argv){if(argc<3){std::cerr<<"usage: integrated_tensorrt_video_pipeline_gpu ENGINE IMAGE [FRAMES=16] [BATCH=4] [SLOTS=2] [OUTPUT]\n";return 2;}try{int frames=argc>3?std::stoi(argv[3]):16,batch=argc>4?std::stoi(argv[4]):4,slot_count=argc>5?std::stoi(argv[5]):2;std::filesystem::path out=argc>6?argv[6]:"21_integrated_tensorrt_video_pipeline/output";if(frames<1||batch<1||batch>4||slot_count<1)throw std::invalid_argument("invalid configuration");cv::Mat image=cv::imread(argv[2]);if(image.empty())throw std::runtime_error("cannot read source");std::filesystem::create_directories(out);std::ofstream detections(out/"detections.jsonl"),metrics(out/"metrics.json");if(!detections||!metrics)throw std::runtime_error("cannot open outputs");lesson21::TensorRtBackend backend(argv[1],slot_count,{640,640});std::deque<size_t> free;for(int i=0;i<slot_count;++i)free.push_back(i);std::deque<Pending> pending;std::uint64_t next_frame=0,next_batch=0,processed=0;std::vector<float> latencies;double preprocess=0,inference=0,d2h=0;auto start=std::chrono::steady_clock::now();auto collect=[&](Pending p){auto result=backend.collect(p.slot);free.push_back(p.slot);size_t n=result.metadata.frames.size(),per=result.output.size()/n;for(size_t i=0;i<n;++i){std::vector<float> slice(result.output.begin()+i*per,result.output.begin()+(i+1)*per);const auto&t=result.metadata.frames[i].transform;lesson11::LetterboxInfo info{t.source_width,t.source_height,640,640,(int)std::round(t.source_width*t.scale),(int)std::round(t.source_height*t.scale),(int)t.pad_x,(int)t.pad_y,0,0,t.scale};auto found=lesson11::decode_yolov8_output(slice,{1,result.output_shape[1],result.output_shape[2]},info,{});if(result.metadata.batch_id==0&&i==0){cv::Mat annotated=image.clone();for(const auto&d:found)cv::rectangle(annotated,{(int)d.box.x1,(int)d.box.y1},{(int)d.box.x2,(int)d.box.y2},{0,255,0},2);if(!cv::imwrite((out/"annotated_0.jpg").string(),annotated))throw std::runtime_error("cannot save annotation");}detections<<"{\"stream_id\":"<<result.metadata.frames[i].stream_id<<",\"frame_id\":"<<result.metadata.frames[i].frame_id<<",\"batch_id\":"<<result.metadata.batch_id<<",\"detections\":[";for(size_t d=0;d<found.size();++d){if(d)detections<<',';detections<<"{\"class_id\":"<<found[d].class_id<<",\"confidence\":"<<found[d].confidence<<",\"box\":["<<found[d].box.x1<<','<<found[d].box.y1<<','<<found[d].box.x2<<','<<found[d].box.y2<<"]}";}detections<<"]}\n";latencies.push_back(std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-result.metadata.frames[i].captured_at).count());++processed;}preprocess+=result.preprocess_ms;inference+=result.inference_ms;d2h+=result.d2h_ms;};while(next_frame<(std::uint64_t)frames||!pending.empty()){while(next_frame<(std::uint64_t)frames&&!free.empty()){size_t n=std::min<std::uint64_t>(batch,frames-next_frame),slot=free.front();free.pop_front();std::vector<cv::Mat> images(n,image);lesson21::BatchMetadata m;m.batch_id=next_batch++;for(size_t i=0;i<n;++i)m.frames.push_back({(next_frame+i)%2,next_frame+i,i,lesson21::Clock::now(),{}});backend.submit(slot,images,std::move(m));pending.push_back({slot,std::chrono::steady_clock::now()});next_frame+=n;}bool collected=false;for(auto it=pending.begin();it!=pending.end();++it)if(backend.ready(it->slot)){auto p=*it;pending.erase(it);collect(p);collected=true;break;}if(!collected&&!pending.empty()){auto p=pending.front();pending.pop_front();collect(p);}}auto elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();std::sort(latencies.begin(),latencies.end());auto pct=[&](double q){return latencies.empty()?0.0:latencies[(size_t)((latencies.size()-1)*q)];};metrics<<"{\"schema_version\":1,\"captured\":"<<frames<<",\"admitted\":"<<frames<<",\"submitted\":"<<frames<<",\"completed\":"<<processed<<",\"processed\":"<<processed<<",\"queue_peak\":0,\"dropped\":0,\"batches\":"<<next_batch<<",\"slots\":"<<slot_count<<",\"preprocess_ms\":"<<preprocess<<",\"inference_ms\":"<<inference<<",\"d2h_ms\":"<<d2h<<",\"p50_ms\":"<<pct(.5)<<",\"p90_ms\":"<<pct(.9)<<",\"p99_ms\":"<<pct(.99)<<",\"fps\":"<<processed/elapsed<<"}\n";std::cout<<"backend=tensorrt captured="<<frames<<" processed="<<processed<<" dropped=0 batches="<<next_batch<<" slots="<<slot_count<<" fps="<<processed/elapsed<<" p50_ms="<<pct(.5)<<" p90_ms="<<pct(.9)<<" p99_ms="<<pct(.99)<<'\n';return processed==(std::uint64_t)frames?0:1;}catch(const std::exception&e){std::cerr<<"error: "<<e.what()<<'\n';return 1;}}
